definition.frag:
vec4 s = texture(u_tex, v_st);
float a = s.a;
if (a <= 0.0001) { o = vec4(0.0); return; }
float r = u_blur;
vec2 jitter = (vec2(hash(v_px), hash(v_px + 17.31)) - 0.5) * u_frost * r * 0.5;
vec3 acc = vec3(0.0);
float wsum = 0.0;
for (int i = 0; i < 64; i++) {
  float fi = float(i);
  float rr = sqrt((fi + 0.5) / 64.0) * r;
  float th = fi * 2.39996323;
  vec2 off = vec2(cos(th), sin(th)) * rr + jitter;
  float w = 1.0 - 0.5 * (rr / max(r, 0.001));
  acc += texture(u_backdrop, v_st + off * u_texel).rgb * w;
  wsum += w;
}
vec3 b = acc / max(wsum, 0.0001);
float l = luma(b);
b = max(mix(vec3(l), b, u_saturation), 0.0);
b = mix(b, vec3(1.0), u_brightness);
b = mix(b, u_tint, u_tintAmount);
vec3 fill = s.rgb / max(a, 0.0001);
b = mix(b, fill, u_fillMix);
vec2 ew = vec2(u_edgeWidth, 0.0) * u_texel.x;
vec2 eh = vec2(0.0, u_edgeWidth) * u_texel.y;
float m = min(min(texture(u_tex, v_st + ew).a, texture(u_tex, v_st - ew).a), min(texture(u_tex, v_st + eh).a, texture(u_tex, v_st - eh).a));
float rim = clamp((a - m) * 2.0, 0.0, 1.0);
b += u_edge * rim * (1.0 - b * 0.5);
b += (hash(v_px * 1.37 + 3.1) - 0.5) * u_grain;
o = vec4(clamp(b, 0.0, 1.0) * a, a);
